import { isPetDoorId, resultsRespectEligibility } from "./collections";
import React, { useEffect, useState } from "react";

// results/index.json (generated by scripts/build_results_index.py; copied into the site by the Pages workflow)
export const RESULTS = "./results";

export type Suite = "core" | "human";
export interface GroupStat { n_doors: number; n_episodes: number; n_success: number; success_rate: number; doors_solved: number; doors_solved_any: number; damage_rate: number; mean_time_to_pass_s: number | null; mean_return?: number | null; human_collision_rate?: number | null }
export interface SuiteBlock {
  suite: Suite; scenarios: string[]; n_doors: number; n_doors_suite: number; complete: boolean;
  doors_solved: number; doors_solved_any: number; n_episodes: number; n_success: number; success_rate: number; damage_rate: number;
  human_collision_rate?: number | null; mean_return?: number | null; mean_time_to_pass_s: number | null; median_time_to_pass_s: number | null;
  outcomes: Record<string, number>; n_errors?: number; mean_wall_s?: number | null;
  by_family: Record<string, GroupStat>; by_scenario: Record<string, GroupStat>; by_difficulty: Record<string, GroupStat>; by_lock_state: Record<string, GroupStat>;
  doors: Record<string, [number, number]>;   // door id -> [n_success, n_episodes] in this suite
}
export interface HistoricalSubset { policy: string; applied: boolean; source_file: string; source_sha256: string; original_n_doors: number; original_n_episodes: number; excluded_door_ids: string[]; excluded_n_doors: number; excluded_n_episodes: number; retained_n_doors: number; retained_n_episodes: number; note: string }
export interface ResultEntry {
  historical_subset?: HistoricalSubset;
  file: string; policy: string; description: string; embodiment: string; policy_class?: string; extra?: Record<string, any>;
  simulator: string; simulator_version?: string | null; tier: string; date: string; label?: string; commit?: string | null; dataset_version?: string | null;
  n_doors_total?: number; suite: string; scenario_filter?: string; n_doors: number; seeds: number[]; scenarios: string[]; randomize?: boolean; time_budget_s?: any;
  wall_time_s?: number; host?: string | null; door_selection?: string;
  leaderboard: boolean;                        // a complete core run (every door, every listed core scenario)
  suites: Partial<Record<Suite, SuiteBlock>>;
}
export interface ResultsIndex { eligibility_policy?: string; n_assets_total?: number; n_doors_supplementary?: number; schema_version: string; generated: string; n_doors_total: number; n_doors_human: number; suites: Record<Suite, string[]>; results: ResultEntry[] }

let cache: ResultsIndex | null | undefined;      // undefined = not fetched, null = missing
let pending: Promise<ResultsIndex | null> | null = null;
const listeners = new Set<(r: ResultsIndex | null) => void>();

export function loadResultsIndex(): Promise<ResultsIndex | null> {
  if (cache !== undefined) return Promise.resolve(cache);
  if (!pending) {
    pending = fetch(`${RESULTS}/index.json`).then((r) => (r.ok ? r.json() : null)).catch(() => null).then((r) => {
      cache = r && r.schema_version === "1.1" ? (r as ResultsIndex) : null;
      listeners.forEach((l) => l(cache!));
      return cache!;
    });
  }
  return pending;
}

/** Shared, fetched-once results index (null when results/index.json is absent, e.g. a fresh clone). */
export function useResultsIndex(): ResultsIndex | null | undefined {
  const [idx, setIdx] = useState<ResultsIndex | null | undefined>(cache);
  useEffect(() => {
    if (cache !== undefined) { setIdx(cache); return; }
    listeners.add(setIdx);
    loadResultsIndex();
    return () => { listeners.delete(setIdx); };
  }, []);
  return idx;
}

export function outcomeClass(s: [number, number] | undefined): string {
  if (!s || s[1] === 0) return "none";
  if (s[0] === s[1]) return "ok";
  if (s[0] === 0) return "bad";
  return "part";
}

/** Small per-door chips: one per leaderboard policy, "policy n/N" (successful episodes / episodes) in the core suite;
 *  with `suite="human"` the same for the human suite (only for doors that list a human scenario). */
export function BaselineBadges({ id, compact = true, suite = "core" }: { id: string; compact?: boolean; suite?: Suite }) {
  const idx = useResultsIndex();
  if (!idx || isPetDoorId(id) || !resultsRespectEligibility(idx)) return null;
  const rows = idx.results.filter((r) => (suite === "core" ? r.leaderboard : r.suites.human?.complete));
  if (!rows.length) return null;
  return (
    <>
      {rows.map((r) => {
        const s = r.suites[suite]?.doors[id];
        const cls = outcomeClass(s);
        const txt = s ? `${s[0]}/${s[1]}` : "–";
        const title = s ? `${r.policy} (${suite} suite): ${s[0]} of ${s[1]} episode(s) successful (${r.simulator} ${r.tier}, ${r.date})` : `${r.policy}: not evaluated in the ${suite} suite`;
        return <span key={r.file} className={`chip res ${cls}`} title={title}>{compact ? r.policy.replace(/_/g, " ") : r.policy}{suite === "human" ? " (human)" : ""} {txt}</span>;
      })}
    </>
  );
}
